python -c "
import json
for m in ['miner_agent_miner_1','miner_agent_miner_2','miner_agent_miner_3']:
    print('===', m, 'last events ===')
    try:
        d = json.load(open(f'../logs/{m}.json'))
        for ev in d[-4:]:
            k = ev.get('event')
            print('-', k)
            if k in ('run_complete','agent_finish','error'):
                print(' ', json.dumps(ev)[:2000])
    except Exception as e:
        print('ERR', e)
    print()
"
